/// Byte-exact C-string equality (`!strcmp(a, b)`), used by the name-lookup
/// walkers below in place of Raven's `strcmp`.
unsafe fn cstr_eq(mut a: *const c_char, mut b: *const c_char) -> bool {
    loop {
        if *a != *b {
            return false;
        }
        if *a == 0 {
            return true;
        }
        a = a.add(1);
        b = b.add(1);
    }
}

