/// Raven `CheatsOk`.
///
/// Source: `oracle/codemp/game/g_cmds.c:109-119`
// PORT-NOTE(raw-ptr-skeleton-no-world-handle): reads the `g_cheats` cvar and
// calls `trap_SendServerCommand`/`G_GetStringEdString`+`ent-g_entities`; no
// GameCvars/engine handle is reachable from this raw-pointer signature.
pub fn CheatsOk(ctx: GameContext<'_>, ent: *mut gentity_t) -> qboolean {
    unsafe {
        if (*ctx.world).cvars.g_cheats.integer == 0 {
            // PORT-NOTE(G_GetStringEdString): OPEN fn (g_main.rs) — called with the
            // packet's cited fixed args; the localized string is substituted into the
            // print command per the va mapping table.
            let msg = crate::g_main::G_GetStringEdString(
                ctx,
                c"MP_SVGAME".as_ptr() as *mut c_char,
                c"NOCHEATS".as_ptr() as *mut c_char,
            );
            let s = format!("print \"{}\n\"", cstr_to_str(msg));
            trap::SendServerCommand(
                ctx.engine,
                mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                    ent_index(ctx, ent),
                    cstr(&s),
                ),
            );
            return qfalse;
        }
        if (*ent).health <= 0 {
            let msg = crate::g_main::G_GetStringEdString(
                ctx,
                c"MP_SVGAME".as_ptr() as *mut c_char,
                c"MUSTBEALIVE".as_ptr() as *mut c_char,
            );
            let s = format!("print \"{}\n\"", cstr_to_str(msg));
            trap::SendServerCommand(
                ctx.engine,
                mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                    ent_index(ctx, ent),
                    cstr(&s),
                ),
            );
            return qfalse;
        }
        qtrue
    }
}

/// Raven `ConcatArgs`.
///
/// Source: `oracle/codemp/game/g_cmds.c:127-152`
// PORT-NOTE(static-scratch-buffer-vs-raw-ptr-return): resolves
// the C `static char line[MAX_STRING_CHARS]` rotating scratch buffer to an owned
// return value, but the staged skeleton return type is `*mut c_char` (a raw,
// presumably-'static pointer into file-scope storage) — can't own a `String` and
// return a raw pointer to it without leaking/aliasing. Also needs `trap_Argc`/
// `trap_Argv`, unreachable without an engine handle.
pub fn ConcatArgs(ctx: GameContext<'_>, start: c_int) -> *mut c_char {
    // DIVERGENCE: Raven returns a pointer into file-scope
    // `static char line[MAX_STRING_CHARS]`; ported callers all consume the
    // result immediately (as `*const c_char`), so a `ctx`-owned scratch buffer
    // on `GameWorld` stands in for the static and is returned as a raw pointer
    // valid until the next `ConcatArgs` call (mirrors the Raven rotating-buffer
    // lifetime discipline used elsewhere for `va`).
    unsafe {
        let c = trap::Argc(ctx.engine, mp_abi::game::syscalls::G_ARGC::GArgcArgs::new());
        let mut len: usize = 0;
        let mut out: Vec<u8> = Vec::new();
        for i in start..c {
            let mut arg = [0 as c_char; MAX_STRING_CHARS];
            trap::Argv(
                ctx.engine,
                mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(
                    i,
                    arg.as_mut_ptr(),
                    MAX_STRING_CHARS as c_int,
                ),
            );
            let s = cstr_to_str(arg.as_ptr());
            let tlen = s.len();
            if len + tlen >= MAX_STRING_CHARS - 1 {
                break;
            }
            out.extend_from_slice(s.as_bytes());
            len += tlen;
            if i != c - 1 {
                out.push(b' ');
                len += 1;
            }
        }
        (*ctx.world).bg_state.concat_args_line = out;
        (*ctx.world).bg_state.concat_args_line.push(0);
        (*ctx.world).bg_state.concat_args_line.as_mut_ptr() as *mut c_char
    }
}

/// Raven `SanitizeString`.
///
/// Remove case and control characters.
///
/// Source: `oracle/codemp/game/g_cmds.c:161-175`
pub fn SanitizeString(r#in: *mut c_char, out: *mut c_char) {
    unsafe {
        let mut i = r#in;
        let mut o = out;
        loop {
            let c = *i as u8;
            if c == 0 {
                break;
            }
            if c == 27 {
                // skip color code
                i = i.add(2);
                continue;
            }
            if (c as i8) < 32 {
                i = i.add(1);
                continue;
            }
            *o = (c as char).to_ascii_lowercase() as c_char;
            o = o.add(1);
            i = i.add(1);
        }
        *o = 0;
    }
}

/// Raven `ClientNumberFromString`.
///
/// Returns a player number for either a number or name string. Returns -1 if invalid.
///
/// Source: `oracle/codemp/game/g_cmds.c:185-221`
// PORT-NOTE(raw-ptr-skeleton-no-world-handle): reads `level.maxclients`,
// `level.clients`, and calls `trap_SendServerCommand`; no GameWorld/engine handle
// reachable from this raw-pointer signature.
pub fn ClientNumberFromString(ctx: GameContext<'_>, to: *mut gentity_t, s: *mut c_char) -> c_int {
    unsafe {
        let world = ctx.world;
        let ss = cstr_to_str(s);

        if let Some(c0) = ss.as_bytes().first() {
            if (*c0 as char).is_ascii_digit() {
                // Source: oracle/codemp/game/g_cmds.c:193 — plain `atoi(s)`.
                let idnum: c_int = atoi(s as *const c_char);
                if idnum < 0 || idnum >= (*world).level.maxclients {
                    let msg = format!("print \"Bad client slot: {}\n\"", idnum);
                    trap::SendServerCommand(
                        ctx.engine,
                        mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                            ent_index(ctx, to),
                            cstr(&msg),
                        ),
                    );
                    return -1;
                }

                let cl = (*world).level.clients.add(idnum as usize);
                if (*cl).pers.connected != CON_CONNECTED {
                    let msg = format!("print \"Client {} is not active\n\"", idnum);
                    trap::SendServerCommand(
                        ctx.engine,
                        mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                            ent_index(ctx, to),
                            cstr(&msg),
                        ),
                    );
                    return -1;
                }
                return idnum;
            }
        }

        // check for a name match
        let mut s2 = [0 as c_char; MAX_STRING_CHARS];
        SanitizeString(s, s2.as_mut_ptr());
        let clients = (*world).level.clients;
        for idnum in 0..(*world).level.maxclients {
            let cl = clients.add(idnum as usize);
            if (*cl).pers.connected != CON_CONNECTED {
                continue;
            }
            let mut n2 = [0 as c_char; MAX_STRING_CHARS];
            SanitizeString((*cl).pers.netname.as_ptr() as *mut c_char, n2.as_mut_ptr());
            if cstr_eq(n2.as_ptr(), s2.as_ptr()) {
                return idnum;
            }
        }

        let msg = format!("print \"User {} is not on the server\n\"", ss);
        trap::SendServerCommand(
            ctx.engine,
            mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                ent_index(ctx, to),
                cstr(&msg),
            ),
        );
        -1
    }
}

/// Raven `Cmd_Give_f`.
///
/// Give items to a client.
///
/// Source: `oracle/codemp/game/g_cmds.c:230-392`
// PORT-NOTE(raw-ptr-skeleton-no-world-handle): calls `CheatsOk` (itself
// parked), reads `g_entities`, calls `trap_Argv`/`trap_Argc`/`Com_Printf`; no
// GameWorld/engine handle reachable from this raw-pointer signature.
pub fn Cmd_Give_f(ctx: GameContext<'_>, cmdent: *mut gentity_t, baseArg: c_int) {
    unsafe {
        if CheatsOk(ctx, cmdent) == qfalse {
            return;
        }

        let ent: *mut gentity_t;
        if baseArg != 0 {
            let mut otherindex = [0 as c_char; MAX_TOKEN_CHARS];
            trap::Argv(
                ctx.engine,
                mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(
                    1,
                    otherindex.as_mut_ptr(),
                    MAX_TOKEN_CHARS as c_int,
                ),
            );

            if otherindex[0] == 0 {
                crate::g_main::Com_Printf(
                    cstr("giveother requires that the second argument be a client index number.\n")
                        .as_ptr(),
                );
                return;
            }

            let i: c_int = atoi_str(&cstr_to_str(otherindex.as_ptr()));

            if !(0..MAX_CLIENTS as c_int).contains(&i) {
                crate::g_main::Com_Printf(cstr(&format!("{} is not a client index\n", i)).as_ptr());
                return;
            }

            ent = &mut (*ctx.world).g_entities[i as usize] as *mut gentity_t;

            if (*ent).inuse == qfalse || (*ent).client.is_null() {
                crate::g_main::Com_Printf(
                    cstr(&format!("{} is not an active client\n", i)).as_ptr(),
                );
                return;
            }
        } else {
            ent = cmdent;
        }

        let client = (*ent).client as *mut gclient_t;

        let mut name = [0 as c_char; MAX_TOKEN_CHARS];
        trap::Argv(
            ctx.engine,
            mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(
                1 + baseArg,
                name.as_mut_ptr(),
                MAX_TOKEN_CHARS as c_int,
            ),
        );
        let name_str = cstr_to_str(name.as_ptr());

        let give_all = name_str.eq_ignore_ascii_case("all");

        if give_all {
            for i in 0..HI_NUM_HOLDABLE {
                (*client).ps.stats[STAT_HOLDABLE_ITEMS as usize] |= 1 << i;
            }
        }

        if give_all || name_str.eq_ignore_ascii_case("health") {
            if trap::Argc(ctx.engine, mp_abi::game::syscalls::G_ARGC::GArgcArgs::new())
                == 3 + baseArg
            {
                let mut arg = [0 as c_char; MAX_TOKEN_CHARS];
                trap::Argv(
                    ctx.engine,
                    mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(
                        2 + baseArg,
                        arg.as_mut_ptr(),
                        MAX_TOKEN_CHARS as c_int,
                    ),
                );
                (*ent).health = atoi_str(&cstr_to_str(arg.as_ptr()));
                if (*ent).health > (*client).ps.stats[STAT_MAX_HEALTH as usize] {
                    (*ent).health = (*client).ps.stats[STAT_MAX_HEALTH as usize];
                }
            } else {
                (*ent).health = (*client).ps.stats[STAT_MAX_HEALTH as usize];
            }
            if !give_all {
                return;
            }
        }

        if give_all || name_str.eq_ignore_ascii_case("weapons") {
            (*client).ps.stats[STAT_WEAPONS as usize] =
                (1 << (LAST_USEABLE_WEAPON + 1)) - (1 << WP_NONE);
            if !give_all {
                return;
            }
        }

        if !give_all && name_str.eq_ignore_ascii_case("weaponnum") {
            let mut arg = [0 as c_char; MAX_TOKEN_CHARS];
            trap::Argv(
                ctx.engine,
                mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(
                    2 + baseArg,
                    arg.as_mut_ptr(),
                    MAX_TOKEN_CHARS as c_int,
                ),
            );
            let n: c_int = atoi_str(&cstr_to_str(arg.as_ptr()));
            (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << n;
            return;
        }

        if give_all || name_str.eq_ignore_ascii_case("ammo") {
            let mut num = 999;
            if trap::Argc(ctx.engine, mp_abi::game::syscalls::G_ARGC::GArgcArgs::new())
                == 3 + baseArg
            {
                let mut arg = [0 as c_char; MAX_TOKEN_CHARS];
                trap::Argv(
                    ctx.engine,
                    mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(
                        2 + baseArg,
                        arg.as_mut_ptr(),
                        MAX_TOKEN_CHARS as c_int,
                    ),
                );
                num = atoi_str(&cstr_to_str(arg.as_ptr()));
            }
            for i in 0..MAX_WEAPONS as usize {
                (*client).ps.ammo[i] = num;
            }
            if !give_all {
                return;
            }
        }

        if give_all || name_str.eq_ignore_ascii_case("armor") {
            if trap::Argc(ctx.engine, mp_abi::game::syscalls::G_ARGC::GArgcArgs::new())
                == 3 + baseArg
            {
                let mut arg = [0 as c_char; MAX_TOKEN_CHARS];
                trap::Argv(
                    ctx.engine,
                    mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(
                        2 + baseArg,
                        arg.as_mut_ptr(),
                        MAX_TOKEN_CHARS as c_int,
                    ),
                );
                (*client).ps.stats[STAT_ARMOR as usize] = atoi_str(&cstr_to_str(arg.as_ptr()));
            } else {
                (*client).ps.stats[STAT_ARMOR as usize] =
                    (*client).ps.stats[STAT_MAX_HEALTH as usize];
            }

            if !give_all {
                return;
            }
        }

        if name_str.eq_ignore_ascii_case("excellent") {
            (*client).ps.persistant[PERS_EXCELLENT_COUNT as usize] += 1;
            return;
        }
        if name_str.eq_ignore_ascii_case("impressive") {
            (*client).ps.persistant[PERS_IMPRESSIVE_COUNT as usize] += 1;
            return;
        }
        if name_str.eq_ignore_ascii_case("gauntletaward") {
            (*client).ps.persistant[PERS_GAUNTLET_FRAG_COUNT as usize] += 1;
            return;
        }
        if name_str.eq_ignore_ascii_case("defend") {
            (*client).ps.persistant[PERS_DEFEND_COUNT as usize] += 1;
            return;
        }
        if name_str.eq_ignore_ascii_case("assist") {
            (*client).ps.persistant[PERS_ASSIST_COUNT as usize] += 1;
            return;
        }

        // spawn a specific item right on the player
        if !give_all {
            let it = crate::bg_misc::BG_FindItem(name.as_ptr());
            if it.is_null() {
                return;
            }

            let it_ent = crate::g_utils::G_Spawn(ctx);
            crate::q_math::_VectorCopy((*ent).r.currentOrigin, &mut (*it_ent).s.origin);
            (*it_ent).classname = (*it).classname;
            crate::g_items::G_SpawnItem(ctx, ctx.entity_id_of(it_ent).unwrap(), it);
            crate::g_items::FinishSpawningItem(ctx, ctx.entity_id_of(it_ent).unwrap());
            let mut trace: trace_t = core::mem::zeroed();
            crate::g_items::Touch_Item(
                ctx,
                ctx.entity_id_of(it_ent).unwrap(),
                ctx.entity_id_of(ent),
                &mut trace,
            );
            if (*it_ent).inuse != qfalse {
                crate::g_utils::G_FreeEntity(ctx, it_ent);
            }
        }
    }
}

/// Raven `Cmd_God_f`.
///
/// Sets client to godmode.
///
/// argv(0) god
///
/// Source: `oracle/codemp/game/g_cmds.c:403-418`
// PORT-NOTE(raw-ptr-skeleton-no-world-handle): calls `CheatsOk` and
// `trap_SendServerCommand`; no GameWorld/engine handle reachable here.
pub fn Cmd_God_f(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        if CheatsOk(ctx, ent) == qfalse {
            return;
        }

        (*ent).flags ^= FL_GODMODE;
        let msg = if (*ent).flags & FL_GODMODE == 0 {
            "godmode OFF\n"
        } else {
            "godmode ON\n"
        };

        let s = format!("print \"{}\"", msg);
        trap::SendServerCommand(
            ctx.engine,
            mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                ent_index(ctx, ent),
                cstr(&s),
            ),
        );
    }
}

