/// Raven `G_GetDuelWinner`.
///
/// Source: `oracle/codemp/game/g_cmds.c:645-661`
pub fn G_GetDuelWinner(ctx: GameContext<'_>, client: *mut gclient_t) -> *mut gentity_t {
    unsafe {
        let world = ctx.world;
        for i in 0..(*world).level.maxclients {
            let wCl = (*world).level.clients.add(i as usize);

            // Faithful to Raven's `if (wCl && wCl != client && …)`.
            if !wCl.is_null()
                && wCl != client
                && (*wCl).pers.connected == CON_CONNECTED
                && (*wCl).sess.sessionTeam != TEAM_SPECTATOR
            {
                let cn = (*wCl).ps.clientNum;
                return &mut (*world).g_entities[cn as usize] as *mut gentity_t;
            }
        }

        core::ptr::null_mut()
    }
}

