/// Raven `G_PowerDuelCheckFail`.
///
/// Source: `oracle/codemp/game/g_cmds.c:720-743`
pub fn G_PowerDuelCheckFail(ctx: GameContext<'_>, ent: *mut gentity_t) -> qboolean {
    // Raven `duelTeam_t` (`bg_public.h:1019-1025`); `gclient_t::sess.duelTeam` is
    // stored as plain `c_int`, so the enum discriminants are transcribed as consts.
    const DUELTEAM_FREE: c_int = 0;
    const DUELTEAM_LONE: c_int = 1;
    const DUELTEAM_DOUBLE: c_int = 2;

    unsafe {
        if (*ent).client.is_null()
            || (*((*ent).client as *mut gclient_t)).sess.duelTeam == DUELTEAM_FREE
        {
            return qtrue;
        }

        let mut loners: c_int = 0;
        let mut doubles: c_int = 0;
        crate::g_main::G_PowerDuelCount(ctx, &mut loners, &mut doubles, qfalse);

        if (*((*ent).client as *mut gclient_t)).sess.duelTeam == DUELTEAM_LONE && loners >= 1 {
            return qtrue;
        }

        if (*((*ent).client as *mut gclient_t)).sess.duelTeam == DUELTEAM_DOUBLE && doubles >= 2 {
            return qtrue;
        }

        qfalse
    }
}

/// Raven `SetTeam`.
///
/// Source: `oracle/codemp/game/g_cmds.c:752-1022`
// PORT-NOTE(raw-ptr-skeleton-no-world-handle): the largest function in the
// file — reads `g_gametype`/`g_teamForceBalance`/`g_trueJedi`/`g_maxGameClients`
// cvars, `level.time`/`level.numNonSpectatorClients`/etc, `g_entities`, and calls
// a dozen trap_*/G_* helpers; no GameWorld/engine handle reachable here. Also
// mutates the file-scope `g_dontPenalizeTeam qboolean` global; becomes a
// GameWorld field once threaded.
pub fn SetTeam(ctx: GameContext<'_>, ent: *mut gentity_t, s: *mut c_char) {
    use crate::client::spectator_state::spectatorState_t::*;
    use mp_bg::public::gametype::{GT_DUEL, GT_POWERDUEL, GT_SIEGE, GT_TEAM};

    unsafe {
        let world = ctx.world;
        let client = (*ent).client as *mut gclient_t;
        let clientNum = client.offset_from((*world).level.clients) as c_int;
        let mut specClient: c_int = 0;
        let mut specState = SPECTATOR_NOT;
        let ss = cstr_to_str(s);
        let mut team: c_int;

        if ss.eq_ignore_ascii_case("scoreboard") || ss.eq_ignore_ascii_case("score") {
            team = TEAM_SPECTATOR;
            specState = SPECTATOR_SCOREBOARD;
        } else if ss.eq_ignore_ascii_case("follow1") {
            team = TEAM_SPECTATOR;
            specState = SPECTATOR_FOLLOW;
            specClient = -1;
        } else if ss.eq_ignore_ascii_case("follow2") {
            team = TEAM_SPECTATOR;
            specState = SPECTATOR_FOLLOW;
            specClient = -2;
        } else if ss.eq_ignore_ascii_case("spectator") || ss.eq_ignore_ascii_case("s") {
            team = TEAM_SPECTATOR;
            specState = SPECTATOR_FREE;
        } else if (*world).cvars.g_gametype.integer >= GT_TEAM {
            specState = SPECTATOR_NOT;
            if ss.eq_ignore_ascii_case("red") || ss.eq_ignore_ascii_case("r") {
                team = TEAM_RED;
            } else if ss.eq_ignore_ascii_case("blue") || ss.eq_ignore_ascii_case("b") {
                team = TEAM_BLUE;
            } else {
                team = crate::g_client::PickTeam(ctx, clientNum) as c_int;
            }

            if (*world).cvars.g_teamForceBalance.integer != 0
                && (*world).cvars.g_trueJedi.integer == 0
            {
                let mut counts = [0 as c_int; TEAM_NUM_TEAMS as usize];
                counts[TEAM_BLUE as usize] =
                    crate::g_client::TeamCount(ctx, (*client).ps.clientNum, TEAM_BLUE) as c_int;
                counts[TEAM_RED as usize] =
                    crate::g_client::TeamCount(ctx, (*client).ps.clientNum, TEAM_RED) as c_int;

                if team == TEAM_RED && counts[TEAM_RED as usize] - counts[TEAM_BLUE as usize] > 1 {
                    let m = crate::g_main::G_GetStringEdString(
                        ctx,
                        c"MP_SVGAME".as_ptr() as *mut c_char,
                        c"TOOMANYRED".as_ptr() as *mut c_char,
                    );
                    let msg = format!("print \"{}\n\"", cstr_to_str(m));
                    trap::SendServerCommand(
                        ctx.engine,
                        mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                            (*client).ps.clientNum,
                            cstr(&msg),
                        ),
                    );
                    return; // ignore the request
                }
                if team == TEAM_BLUE && counts[TEAM_BLUE as usize] - counts[TEAM_RED as usize] > 1 {
                    let m = crate::g_main::G_GetStringEdString(
                        ctx,
                        c"MP_SVGAME".as_ptr() as *mut c_char,
                        c"TOOMANYBLUE".as_ptr() as *mut c_char,
                    );
                    let msg = format!("print \"{}\n\"", cstr_to_str(m));
                    trap::SendServerCommand(
                        ctx.engine,
                        mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                            (*client).ps.clientNum,
                            cstr(&msg),
                        ),
                    );
                    return; // ignore the request
                }
            }
        } else {
            team = TEAM_FREE;
        }

        if (*world).cvars.g_gametype.integer == GT_SIEGE {
            if (*client).tempSpectate >= (*world).level.time && team == TEAM_SPECTATOR {
                // sorry, can't do that.
                return;
            }

            (*client).sess.siegeDesiredTeam = team;

            if (*client).sess.sessionTeam != TEAM_SPECTATOR && team != TEAM_SPECTATOR {
                let doBegin = (*client).tempSpectate < (*world).level.time;

                if doBegin {
                    if (*ent).health > 0 {
                        (*ent).flags &= !FL_GODMODE;
                        (*client).ps.stats[STAT_HEALTH as usize] = 0;
                        (*ent).health = 0;
                        crate::g_combat::player_die(
                            ctx,
                            ent,
                            ent,
                            ent,
                            100000,
                            MOD_TEAM_CHANGE as c_int,
                        );
                    }
                }

                if (*client).sess.sessionTeam != (*client).sess.siegeDesiredTeam {
                    crate::g_saga::SetTeamQuick(ctx, ent, (*client).sess.siegeDesiredTeam, qfalse);
                }

                return;
            }
        }

        // override decision if limiting the players
        if (*world).cvars.g_gametype.integer == GT_DUEL
            && (*world).level.numNonSpectatorClients >= 2
        {
            team = TEAM_SPECTATOR;
        } else if (*world).cvars.g_gametype.integer == GT_POWERDUEL
            && ((*world).level.numPlayingClients >= 3 || G_PowerDuelCheckFail(ctx, ent) != qfalse)
        {
            team = TEAM_SPECTATOR;
        } else if (*world).cvars.g_maxGameClients.integer > 0
            && (*world).level.numNonSpectatorClients >= (*world).cvars.g_maxGameClients.integer
        {
            team = TEAM_SPECTATOR;
        }

        let oldTeam = (*client).sess.sessionTeam;
        if team == oldTeam && team != TEAM_SPECTATOR {
            return;
        }

        // if the player was dead leave the body
        if (*client).ps.stats[STAT_HEALTH as usize] <= 0
            && (*client).sess.sessionTeam != TEAM_SPECTATOR
        {
            crate::g_client::MaintainBodyQueue(ctx, ent);
        }

        // he starts at 'base'
        (*client).pers.teamState.state = playerTeamStateState_t::TEAM_BEGIN;
        if oldTeam != TEAM_SPECTATOR {
            (*ent).flags &= !FL_GODMODE;
            (*client).ps.stats[STAT_HEALTH as usize] = 0;
            (*ent).health = 0;
            (*world).globals.g_dontPenalizeTeam = qtrue;
            crate::g_combat::player_die(ctx, ent, ent, ent, 100000, MOD_SUICIDE as c_int);
            (*world).globals.g_dontPenalizeTeam = qfalse;
        }
        if team == TEAM_SPECTATOR {
            if (*world).cvars.g_gametype.integer != GT_DUEL || oldTeam != TEAM_SPECTATOR {
                (*client).sess.spectatorTime = (*world).level.time;
            }
        }

        (*client).sess.sessionTeam = team;
        (*client).sess.spectatorState = specState;
        (*client).sess.spectatorClient = specClient;

        (*client).sess.teamLeader = qfalse;
        if team == TEAM_RED || team == TEAM_BLUE {
            let teamLeader = crate::g_client::TeamLeader(ctx, team);
            if teamLeader == -1
                || ((*world).g_entities[clientNum as usize].r.svFlags & SVF_BOT == 0
                    && (*world).g_entities[teamLeader as usize].r.svFlags & SVF_BOT != 0)
            {
                //SetLeader( team, clientNum );
            }
        }
        if oldTeam == TEAM_RED || oldTeam == TEAM_BLUE {
            crate::g_main::CheckTeamLeader(ctx, oldTeam);
        }

        BroadcastTeamChange(ctx, client, oldTeam);

        if oldTeam != TEAM_SPECTATOR {
            let tent = crate::g_utils::G_TempEntity(
                ctx,
                (*client).ps.origin,
                EV_PLAYER_TELEPORT_OUT as c_int,
            );
            (*tent).s.clientNum = clientNum;
        }

        crate::g_client::ClientUserinfoChanged(ctx, clientNum);

        if (*world).globals.g_preventTeamBegin == qfalse {
            crate::g_client::ClientBegin(ctx, clientNum, qfalse);
        }
    }
}

/// Raven `StopFollowing`.
///
/// If the client being followed leaves the game, or you just want to drop
/// to free floating spectator mode.
///
/// Source: `oracle/codemp/game/g_cmds.c:1032-1051`
// PORT-NOTE(raw-ptr-skeleton-no-world-handle): computes `ent - g_entities`
// (client slot index) to set `ps.clientNum`; no GameWorld/engine handle reachable
// to locate the `g_entities` base here.
pub fn StopFollowing(ctx: GameContext<'_>, ent: *mut gentity_t) {
    use crate::client::spectator_state::spectatorState_t::SPECTATOR_FREE;

    unsafe {
        let client = (*ent).client as *mut gclient_t;
        (*client).ps.persistant[PERS_TEAM as usize] = TEAM_SPECTATOR;
        (*client).sess.sessionTeam = TEAM_SPECTATOR;
        (*client).sess.spectatorState = SPECTATOR_FREE;
        (*client).ps.pm_flags &= !PMF_FOLLOW;
        (*ent).r.svFlags &= !SVF_BOT;
        (*client).ps.clientNum = ent_index(ctx, ent);
        (*client).ps.weapon = WP_NONE;
        (*client).ps.m_iVehicleNum = 0;
        (*client).ps.viewangles[ROLL as usize] = 0.0f32;
        (*client).ps.forceHandExtend = HANDEXTEND_NONE as c_int;
        (*client).ps.forceHandExtendTime = 0;
        (*client).ps.zoomMode = 0;
        (*client).ps.zoomLocked = 0;
        (*client).ps.zoomLockTime = 0;
        (*client).ps.legsAnim = 0;
        (*client).ps.legsTimer = 0;
        (*client).ps.torsoAnim = 0;
        (*client).ps.torsoTimer = 0;
    }
}

/// Raven `Cmd_Team_f`.
///
/// Source: `oracle/codemp/game/g_cmds.c:1058-1112`
// PORT-NOTE(raw-ptr-skeleton-no-world-handle): reads `level.time`,
// `gEscaping`, `g_gametype`/`g_allowDuelSuicide` cvars, calls `trap_Argc`/
// `trap_Argv`/`trap_SendServerCommand`/`SetTeam`; no GameWorld/engine handle
// reachable here.
pub fn Cmd_Team_f(ctx: GameContext<'_>, ent: *mut gentity_t) {
    use mp_bg::public::gametype::{GT_DUEL, GT_POWERDUEL};

    unsafe {
        let world = ctx.world;
        let client = (*ent).client as *mut gclient_t;

        if trap::Argc(ctx.engine, mp_abi::game::syscalls::G_ARGC::GArgcArgs::new()) != 2 {
            let oldTeam = (*client).sess.sessionTeam;
            let key = match oldTeam {
                TEAM_BLUE => Some("PRINTBLUETEAM"),
                TEAM_RED => Some("PRINTREDTEAM"),
                TEAM_FREE => Some("PRINTFREETEAM"),
                TEAM_SPECTATOR => Some("PRINTSPECTEAM"),
                _ => None,
            };
            if let Some(k) = key {
                let m = crate::g_main::G_GetStringEdString(
                    ctx,
                    c"MP_SVGAME".as_ptr() as *mut c_char,
                    cstr(k).as_ptr() as *mut c_char,
                );
                let s = format!("print \"{}\n\"", cstr_to_str(m));
                trap::SendServerCommand(
                    ctx.engine,
                    mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                        ent_index(ctx, ent),
                        cstr(&s),
                    ),
                );
            }
            return;
        }

        if (*client).switchTeamTime > (*world).level.time {
            let m = crate::g_main::G_GetStringEdString(
                ctx,
                c"MP_SVGAME".as_ptr() as *mut c_char,
                c"NOSWITCH".as_ptr() as *mut c_char,
            );
            let s = format!("print \"{}\n\"", cstr_to_str(m));
            trap::SendServerCommand(
                ctx.engine,
                mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                    ent_index(ctx, ent),
                    cstr(&s),
                ),
            );
            return;
        }

        if (*world).globals.gEscaping != qfalse {
            return;
        }

        if (*world).cvars.g_gametype.integer == GT_DUEL && (*client).sess.sessionTeam == TEAM_FREE {
            trap::SendServerCommand(
                ctx.engine,
                mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                    ent_index(ctx, ent),
                    cstr("print \"Cannot switch teams in Duel\n\""),
                ),
            );
            return;
        }

        if (*world).cvars.g_gametype.integer == GT_POWERDUEL {
            trap::SendServerCommand(
                ctx.engine,
                mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                    ent_index(ctx, ent),
                    cstr("print \"Cannot switch teams in Power Duel\n\""),
                ),
            );
            return;
        }

        let mut s = [0 as c_char; MAX_TOKEN_CHARS];
        trap::Argv(
            ctx.engine,
            mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(
                1,
                s.as_mut_ptr(),
                MAX_TOKEN_CHARS as c_int,
            ),
        );

        SetTeam(ctx, ent, s.as_mut_ptr());

        (*client).switchTeamTime = (*world).level.time + 5000;
    }
}

/// Raven `Cmd_DuelTeam_f`.
///
/// Source: `oracle/codemp/game/g_cmds.c:1119-1204`
// PORT-NOTE(raw-ptr-skeleton-no-world-handle): reads `g_gametype` cvar and
// `level.time`, calls `trap_Argc`/`trap_Argv`/`trap_SendServerCommand`/`G_Damage`/
// `ClientUserinfoChanged`; no GameWorld/engine handle reachable here.
pub fn Cmd_DuelTeam_f(ctx: GameContext<'_>, ent: *mut gentity_t) {
    use mp_bg::public::gametype::GT_POWERDUEL;

    const DUELTEAM_FREE: c_int = 0;
    const DUELTEAM_LONE: c_int = 1;
    const DUELTEAM_DOUBLE: c_int = 2;

    unsafe {
        let world = ctx.world;
        let client = (*ent).client as *mut gclient_t;

        if (*world).cvars.g_gametype.integer != GT_POWERDUEL {
            return;
        }

        if trap::Argc(ctx.engine, mp_abi::game::syscalls::G_ARGC::GArgcArgs::new()) != 2 {
            let oldTeam = (*client).sess.duelTeam;
            let msg = match oldTeam {
                DUELTEAM_FREE => Some("print \"None\n\""),
                DUELTEAM_LONE => Some("print \"Single\n\""),
                DUELTEAM_DOUBLE => Some("print \"Double\n\""),
                _ => None,
            };
            if let Some(m) = msg {
                trap::SendServerCommand(
                    ctx.engine,
                    mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                        ent_index(ctx, ent),
                        cstr(m),
                    ),
                );
            }
            return;
        }

        if (*client).switchDuelTeamTime > (*world).level.time {
            let m = crate::g_main::G_GetStringEdString(
                ctx,
                c"MP_SVGAME".as_ptr() as *mut c_char,
                c"NOSWITCH".as_ptr() as *mut c_char,
            );
            let s = format!("print \"{}\n\"", cstr_to_str(m));
            trap::SendServerCommand(
                ctx.engine,
                mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                    ent_index(ctx, ent),
                    cstr(&s),
                ),
            );
            return;
        }

        let mut s = [0 as c_char; MAX_TOKEN_CHARS];
        trap::Argv(
            ctx.engine,
            mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(
                1,
                s.as_mut_ptr(),
                MAX_TOKEN_CHARS as c_int,
            ),
        );
        let ss = cstr_to_str(s.as_ptr());

        let oldTeam = (*client).sess.duelTeam;

        if ss.eq_ignore_ascii_case("free") {
            (*client).sess.duelTeam = DUELTEAM_FREE;
        } else if ss.eq_ignore_ascii_case("single") {
            (*client).sess.duelTeam = DUELTEAM_LONE;
        } else if ss.eq_ignore_ascii_case("double") {
            (*client).sess.duelTeam = DUELTEAM_DOUBLE;
        } else {
            let msg = format!("print \"'{}' not a valid duel team.\n\"", ss);
            trap::SendServerCommand(
                ctx.engine,
                mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                    ent_index(ctx, ent),
                    cstr(&msg),
                ),
            );
        }

        if oldTeam == (*client).sess.duelTeam {
            return;
        }

        if (*client).sess.sessionTeam != TEAM_SPECTATOR {
            let curTeam = (*client).sess.duelTeam;
            (*client).sess.duelTeam = oldTeam;
            crate::g_combat::G_Damage(
                ctx,
                ent,
                ent,
                ent,
                None,
                (*client).ps.origin,
                99999,
                DAMAGE_NO_PROTECTION,
                MOD_SUICIDE as c_int,
            );
            (*client).sess.duelTeam = curTeam;
        }
        (*client).sess.wins = 0;
        (*client).sess.losses = 0;

        crate::g_client::ClientUserinfoChanged(ctx, (*ent).s.number);

        (*client).switchDuelTeamTime = (*world).level.time + 5000;
    }
}

/// Raven `G_TeamForSiegeClass`.
///
/// Source: `oracle/codemp/game/g_cmds.c:1206-1244`
pub fn G_TeamForSiegeClass(ctx: GameContext<'_>, clName: *const c_char) -> c_int {
    // Siege team ids (distinct from `team_t` RED/BLUE) and the 128-class cap,
    // canonical in `mp_bg::saga`. The former local `MAX_SIEGE_CLASSES` was
    // wrongly 12 (oracle is 128).
    // Source: `oracle/codemp/game/bg_saga.h:3-4,12`
    use mp_bg::saga::siege_class_t::MAX_SIEGE_CLASSES;
    use mp_bg::saga::siege_team_t::{SIEGETEAM_TEAM1, SIEGETEAM_TEAM2};

    unsafe {
        let bg = &(*ctx.world).bg_state;
        let mut team = SIEGETEAM_TEAM1;
        let mut i: c_int = 0;
        let mut stm = crate::bg_saga::BG_SiegeFindThemeForTeam(team, bg);

        if stm.is_null() {
            return 0;
        }

        while team <= SIEGETEAM_TEAM2 {
            let scl = (*stm).classes[i as usize];

            if !scl.is_null() && (*scl).name[0] != 0 {
                if crate::q_shared::Q_stricmp(clName, (*scl).name.as_ptr()) == 0 {
                    return team;
                }
            }

            i += 1;
            if i >= MAX_SIEGE_CLASSES as c_int || i >= (*stm).numClasses {
                if team == SIEGETEAM_TEAM2 {
                    break;
                }
                team = SIEGETEAM_TEAM2;
                stm = crate::bg_saga::BG_SiegeFindThemeForTeam(team, bg);
                i = 0;
            }
        }

        0
    }
}

/// Raven `Cmd_SiegeClass_f`.
///
/// Source: `oracle/codemp/game/g_cmds.c:1251-1348`
// PORT-NOTE(raw-ptr-skeleton-no-world-handle): reads `g_gametype` cvar and
// `level.time`, calls `trap_Argc`/`trap_Argv`/`trap_SendServerCommand`/`SetTeam`/
// `BG_SiegeCheckClassLegality`/`ClientUserinfoChanged`/`player_die`/`ClientBegin`;
// no GameWorld/engine handle reachable here. Also mutates file-scope
// `g_preventTeamBegin`.
pub fn Cmd_SiegeClass_f(ctx: GameContext<'_>, ent: *mut gentity_t) {
    use mp_bg::public::gametype::GT_SIEGE;

    unsafe {
        let world = ctx.world;
        let mut className = [0 as c_char; 64];
        let mut startedAsSpec = qfalse;

        if (*world).cvars.g_gametype.integer != GT_SIEGE {
            return;
        }

        if (*ent).client.is_null() {
            return;
        }

        if trap::Argc(ctx.engine, mp_abi::game::syscalls::G_ARGC::GArgcArgs::new()) < 1 {
            return;
        }

        let client = (*ent).client as *mut gclient_t;

        if (*client).switchClassTime > (*world).level.time {
            let m = crate::g_main::G_GetStringEdString(
                ctx,
                c"MP_SVGAME".as_ptr() as *mut c_char,
                c"NOCLASSSWITCH".as_ptr() as *mut c_char,
            );
            let s = format!("print \"{}\n\"", cstr_to_str(m));
            trap::SendServerCommand(
                ctx.engine,
                mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                    ent_index(ctx, ent),
                    cstr(&s),
                ),
            );
            return;
        }

        if (*client).sess.sessionTeam == TEAM_SPECTATOR {
            startedAsSpec = qtrue;
        }

        trap::Argv(
            ctx.engine,
            mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(1, className.as_mut_ptr(), 64),
        );

        let team = G_TeamForSiegeClass(ctx, className.as_ptr());

        if team == 0 {
            return;
        }

        if (*client).sess.sessionTeam != team {
            (*world).globals.g_preventTeamBegin = qtrue;
            if team == TEAM_RED {
                SetTeam(ctx, ent, c"red".as_ptr() as *mut c_char);
            } else if team == TEAM_BLUE {
                SetTeam(ctx, ent, c"blue".as_ptr() as *mut c_char);
            }
            (*world).globals.g_preventTeamBegin = qfalse;

            if (*client).sess.sessionTeam != team {
                if (*client).sess.sessionTeam != TEAM_SPECTATOR
                    || (*client).sess.siegeDesiredTeam != team
                {
                    let m = crate::g_main::G_GetStringEdString(
                        ctx,
                        c"MP_SVGAME".as_ptr() as *mut c_char,
                        c"NOCLASSTEAM".as_ptr() as *mut c_char,
                    );
                    let s = format!("print \"{}\n\"", cstr_to_str(m));
                    trap::SendServerCommand(
                        ctx.engine,
                        mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                            ent_index(ctx, ent),
                            cstr(&s),
                        ),
                    );
                    return;
                }
            }
        }

        let preScore = (*client).ps.persistant[PERS_SCORE as usize];

        crate::bg_saga::BG_SiegeCheckClassLegality(
            team,
            className.as_mut_ptr(),
            &mut (*world).bg_state,
        );

        write_cstr_field(
            &mut (*client).sess.siegeClass,
            &cstr_to_str(className.as_ptr()),
        );

        crate::g_client::ClientUserinfoChanged(ctx, (*ent).s.number);

        if (*client).tempSpectate < (*world).level.time {
            if (*ent).health > 0 && startedAsSpec == qfalse {
                (*ent).flags &= !FL_GODMODE;
                (*client).ps.stats[STAT_HEALTH as usize] = 0;
                (*ent).health = 0;
                crate::g_combat::player_die(ctx, ent, ent, ent, 100000, MOD_SUICIDE as c_int);
            }

            if (*client).sess.sessionTeam == TEAM_SPECTATOR || startedAsSpec != qfalse {
                crate::g_client::ClientBegin(ctx, (*ent).s.number, qfalse);
            }
        }
        (*client).ps.persistant[PERS_SCORE as usize] = preScore;

        (*client).switchClassTime = (*world).level.time + 5000;
    }
}

/// Raven `Cmd_ForceChanged_f`.
///
/// Source: `oracle/codemp/game/g_cmds.c:1355-1392`
// PORT-NOTE(raw-ptr-skeleton-no-world-handle): reads `g_gametype` cvar,
// calls `WP_InitForcePowers`/`G_GetStringEdString`/`trap_SendServerCommand`/
// `trap_Argc`/`trap_Argv`/`Cmd_Team_f`; no GameWorld/engine handle reachable here.
pub fn Cmd_ForceChanged_f(ctx: GameContext<'_>, ent: *mut gentity_t) {
    use mp_bg::public::gametype::{GT_DUEL, GT_POWERDUEL};

    unsafe {
        let world = ctx.world;
        let client = (*ent).client as *mut gclient_t;

        // Raven's `goto argCheck` is preserved here as the natural fall-through of
        // the if/else below (both arms reach the same trailing logic) — see §C10.
        if (*client).sess.sessionTeam == TEAM_SPECTATOR {
            crate::w_force::WP_InitForcePowers(ctx, ent);
        } else {
            let buf = crate::g_main::G_GetStringEdString(
                ctx,
                c"MP_SVGAME".as_ptr() as *mut c_char,
                c"FORCEPOWERCHANGED".as_ptr() as *mut c_char,
            );
            let fpChStr = cstr_to_str(buf);
            let s = format!(
                "print \"{}{}\n\n\"",
                S_COLOR_GREEN.to_string_lossy(),
                fpChStr
            );
            trap::SendServerCommand(
                ctx.engine,
                mp_abi::game::syscalls::G_SEND_SERVER_COMMAND::GSendServerCommandArgs::new(
                    ent_index(ctx, ent),
                    cstr(&s),
                ),
            );

            (*client).ps.fd.forceDoInit = 1;
        }

        if (*world).cvars.g_gametype.integer == GT_DUEL
            || (*world).cvars.g_gametype.integer == GT_POWERDUEL
        {
            return;
        }

        if trap::Argc(ctx.engine, mp_abi::game::syscalls::G_ARGC::GArgcArgs::new()) > 1 {
            let mut arg = [0 as c_char; MAX_TOKEN_CHARS];
            trap::Argv(
                ctx.engine,
                mp_abi::game::syscalls::G_ARGV::GArgvArgs::new(
                    1,
                    arg.as_mut_ptr(),
                    MAX_TOKEN_CHARS as c_int,
                ),
            );

            if arg[0] != 0 {
                Cmd_Team_f(ctx, ent);
            }
        }
    }
}

