            let m = crate::g_main::G_GetStringEdString(
                ctx,
                c"MP_SVGAME".as_ptr() as *mut c_char,
                c"VOTEALREADY".as_ptr() as *mut c_char,
            );
            let s = format!("print \"{}\n\"", cstr_to_str(m));
